package cl.acis.ordenes.model; import jakarta.persistence.*; import java.time.LocalDateTime;
@Entity @Table(name="eventos_orden") public class EventoOrden { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) Long id; @ManyToOne(fetch=FetchType.LAZY,optional=false) @JoinColumn(name="orden_id") OrdenTrabajo orden; @Enumerated(EnumType.STRING) TipoEvento tipo; @Enumerated(EnumType.STRING) EstadoOrden estadoAnterior,estadoNuevo; Long actorId; String detalle; LocalDateTime fecha;
 public EventoOrden(){} public EventoOrden(OrdenTrabajo o,TipoEvento t,EstadoOrden a,EstadoOrden n,Long actor,String d){orden=o;tipo=t;estadoAnterior=a;estadoNuevo=n;actorId=actor;detalle=d;fecha=LocalDateTime.now();} public Long getId(){return id;} public TipoEvento getTipo(){return tipo;} public EstadoOrden getEstadoAnterior(){return estadoAnterior;} public EstadoOrden getEstadoNuevo(){return estadoNuevo;} public Long getActorId(){return actorId;} public String getDetalle(){return detalle;} public LocalDateTime getFecha(){return fecha;}
}
